      const matchesTags =
        selectedTags.length === 0 ||
        selectedTags.every((tag) =>
          Array.isArray(product.tags) && product.tags.includes(tag)
        )

      return matchesSearch && matchesTags
    })
  }, [products, searchQuery, selectedTags])

  return {
    searchQuery,
    setSearchQuery,
    selectedTags,
    toggleTag,
    filteredProducts,
    allTags,
  }
