  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  });
}

function err(message: string, status: number): Response {
  return json({ error: message }, status);
}

// ─── Validation ───────────────────────────────────────────────────────────────

function validateRequest(
  body: unknown
): { data: CreatePaymentIntentRequest } | { error: string } {
  if (!body || typeof body !== 'object') {
    return { error: 'Request body must be a JSON object' };
  }

  const b = body as Record<string, unknown>;

  // Validate items array
  if (!Array.isArray(b.items) || b.items.length === 0) {
    return { error: 'items must be a non-empty array' };
  }

  for (const item of b.items) {
    if (!item || typeof item !== 'object') {
      return { error: 'Each item must be an object' };
    }
    const i = item as Record<string, unknown>;
    if (typeof i.product_id !== 'string' || !i.product_id.trim()) {
      return { error: 'Each item must have a valid product_id string' };
    }
    if (
      typeof i.quantity !== 'number' ||
      !Number.isInteger(i.quantity) ||
      i.quantity < 1
    ) {
      return { error: 'Each item quantity must be a positive integer' };
    }
  }

  // Validate customer object
  const c = b.customer as Record<string, unknown> | undefined;
  if (!c || typeof c !== 'object') {
    return { error: 'customer must be an object' };
  }

  const requiredCustomerFields: (keyof CheckoutCustomer)[] = [
    'name',
    'email',
    'street',
    'city',
    'postal_code',
    'country',
  ];

  for (const field of requiredCustomerFields) {
    if (typeof c[field] !== 'string' || !(c[field] as string).trim()) {
      return { error: `customer.${field} must be a non-empty string` };
    }
  }

  // Basic email sanity check — not RFC-exhaustive, catches obvious mistakes
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email as string)) {
    return { error: 'customer.email is not a valid email address' };
  }

  return {
    data: body as CreatePaymentIntentRequest,
  };
