  // ── 0. Parse body ────────────────────────────────────────────────────────
  let rawBody: unknown;
  try {
    rawBody = await req.json();
  } catch {
    return err('Invalid JSON body', 400);
  }

  // ── 1. Validate input shape before touching DB or Stripe ─────────────────
  const validated = validateRequest(rawBody);
  if ('error' in validated) {
    return err(validated.error, 400);
  }
  const { items, customer } = validated.data;

  // ── Bootstrap clients (after validation — no point building them earlier) ─
  const supabase = createClient(
    Deno.env.get('SUPABASE_URL') ?? '',
    // Service role key required: orders table RLS blocks inserts for anon/user roles
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
  );

  const stripe = new Stripe(Deno.env.get('STRIPE_SECRET_KEY') ?? '', {
    // deno-specific fetch — avoids Node http module
    httpClient: Stripe.createFetchHttpClient(),
    apiVersion: '2023-10-16',
  });

  // ── 2. Fetch products from DB — never trust client prices ─────────────────
  const productIds = items.map((i) => i.product_id);

  const { data: products, error: productFetchError } = await supabase
    .from('products')
    .select('id, name, price, is_available')
    .in('id', productIds);

  if (productFetchError) {
    console.error('Product fetch error:', productFetchError);
    return err('Failed to fetch products', 500);
  }

  // Ensure every requested product_id exists in DB
  const productMap = new Map<string, DbProduct>(
    (products ?? []).map((p: DbProduct) => [p.id, p])
  );

  for (const item of items) {
    if (!productMap.has(item.product_id)) {
      return err(`Product not found: ${item.product_id}`, 400);
    }
    // Reject unavailable products — don't let stale carts slip through
    if (!productMap.get(item.product_id)!.is_available) {
      return err(`Product is no longer available: ${item.product_id}`, 400);
    }
  }

  // ── 3. Calculate total from DB prices only ────────────────────────────────
  let totalCents = 0;
  for (const item of items) {
    const product = productMap.get(item.product_id)!;
    totalCents += product.price * item.quantity;
  }

  // Stripe minimum is 50 cents; catch this before the API call
  if (totalCents < 50) {
    return err('Order total is below the minimum chargeable amount', 400);
  }

  // ── 4. Create Stripe PaymentIntent ───────────────────────────────────────
  let paymentIntent: Stripe.PaymentIntent;
  try {
    paymentIntent = await stripe.paymentIntents.create({
      amount: totalCents,
      currency: 'eur',
      // Attach email for Stripe dashboard visibility & receipt emails
      receipt_email: customer.email,
      metadata: {
        customer_email: customer.email,
        customer_name: customer.name,
      },
    });
  } catch (stripeError) {
    console.error('Stripe PaymentIntent creation failed:', stripeError);
    return err('Payment initialisation failed', 502);
  }

  // ── 5. Insert order row via RPC (service role bypasses RLS) ───────────────
  // If this fails, the PI is dangling but expires in 24h and never charges.
  // Acceptable per spec — no compensating transaction needed here.
  const { data: orderData, error: orderError } = await supabase.rpc(
    'insert_order',
    {
      p_stripe_payment_id: paymentIntent.id,
      p_status: 'order_received',
      p_total: totalCents,
      p_customer_name: customer.name,
      p_customer_email: customer.email,
      p_shipping_street: customer.street,
      p_shipping_city: customer.city,
      p_shipping_postal_code: customer.postal_code,
      p_shipping_country: customer.country,
    }
  );

  if (orderError || !orderData) {
    console.error('Order insert error:', orderError);
    // PI is dangling — log for ops alerting, but don't charge client
    return err('Failed to create order record', 500);
  }

  const orderId: string = orderData;

  // ── 6. Insert order_items rows via RPC ────────────────────────────────────
  const orderItems = items.map((item) => ({
    order_id: orderId,
    product_id: item.product_id,
    quantity: item.quantity,
    // Snapshot price at purchase time — product price may change later
    price_at_purchase: productMap.get(item.product_id)!.price,
  }));

  const { error: itemsError } = await supabase.rpc('insert_order_items', {
    p_items: orderItems,
  });

  if (itemsError) {
    // Order header exists but items missing — log for reconciliation
    // PI still dangling-safe; we log order_id so ops can fix manually
    console.error(`Order items insert failed for order ${orderId}:`, itemsError);
    return err('Failed to create order items', 500);
  }

  // ── 7. Return clientSecret to frontend ───────────────────────────────────
  return json({ clientSecret: paymentIntent.client_secret });
});
